public class Main {
    public static void main(String[] args) {
        System.out.println("=== 01: JVM Architecture & Memory Regions ===");
        Runtime rt = Runtime.getRuntime();
        long maxMemoryMB = rt.maxMemory() / (1024 * 1024);
        long totalMemoryMB = rt.totalMemory() / (1024 * 1024);
        long freeMemoryMB = rt.freeMemory() / (1024 * 1024);

        System.out.printf("Max Heap (-Xmx)   : %d MB%n", maxMemoryMB);
        System.out.printf("Total Allocated   : %d MB%n", totalMemoryMB);
        System.out.printf("Free Memory in JVM: %d MB%n", freeMemoryMB);
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 02: Primitives & Integer Cache (-128 to 127) ===");

        // Integer Cache Trap
        Integer a = 127;
        Integer b = 127;
        System.out.println("127 == 127 (Cached pool)  : " + (a == b)); // true

        Integer x = 128;
        Integer y = 128;
        System.out.println("128 == 128 (Fresh objects) : " + (x == y)); // false!
        System.out.println("128.equals(128) (Value)   : " + x.equals(y)); // true

        // Local variable type inference (var)
        var greeting = "Hello, Modern Java";
        System.out.println("Inferred var: " + greeting);
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 03: Strings & String Constant Pool ===");

        String s1 = "Java";
        String s2 = "Java";
        String s3 = new String("Java");

        System.out.println("s1 == s2 (Constant Pool): " + (s1 == s2)); // true
        System.out.println("s1 == s3 (Heap Object)  : " + (s1 == s3)); // false
        System.out.println("s1 == s3.intern()       : " + (s1 == s3.intern())); // true

        // Text Block (Java 15+)
        String json = """
            {
                "language": "Java",
                "track": "Trak"
            }
            """;
        System.out.println("Text Block:\n" + json);
    }
}

public class Main {
    public static String evaluateScore(int score) {
        return switch (score / 10) {
            case 10, 9 -> "A (Outstanding)";
            case 8 -> "B (Good)";
            case 7 -> "C (Average)";
            default -> {
                System.out.println("Need improvement");
                yield "F (Fail)";
            }
        };
    }

    public static void main(String[] args) {
        System.out.println("=== 04: Modern Switch Expressions & Pattern Matching ===");
        System.out.println("Score 95: " + evaluateScore(95));

        // Pattern matching for instanceof (Java 16+)
        Object obj = "Java 21 LTS";
        if (obj instanceof String s && s.length() > 5) {
            System.out.println("Matched String: " + s.toUpperCase());
        }
    }
}

abstract class Animal {
    private final String name;
    public Animal(String name) { this.name = name; }
    public String getName() { return name; }
    public abstract void makeSound();
}

class Dog extends Animal {
    public Dog(String name) { super(name); }
    @Override
    public void makeSound() {
        System.out.println(getName() + " says: Woof!");
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 05: OOP & Polymorphism ===");
        Animal pet = new Dog("Buddy");
        pet.makeSound();
    }
}

// 1. Modern Record (Immutable data carrier with automatic constructor, getters, equals, hashCode, toString)
record UserRecord(long id, String username, String email) {}

// 2. Sealed Hierarchy (Java 17+)
sealed interface PaymentResult permits Success, Failure {}

record Success(String transactionId) implements PaymentResult {}
record Failure(String errorMessage) implements PaymentResult {}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 06: Records & Sealed Classes (Java 17-21) ===");
        UserRecord user = new UserRecord(101L, "navnath", "navnath@example.com");
        System.out.println("Record: " + user);

        PaymentResult result = new Success("tx_998877");
        if (result instanceof Success(String txId)) {
            System.out.println("Payment Succeeded with Transaction ID: " + txId);
        }
    }
}

import java.util.List;

public class Main {
    // PECS: Producer Extends, Consumer Super
    public static double sumOfNumbers(List<? extends Number> numbers) {
        double sum = 0.0;
        for (Number n : numbers) {
            sum += n.doubleValue();
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println("=== 07: Generics, Type Erasure & PECS Rule ===");
        List<Integer> ints = List.of(1, 2, 3, 4);
        System.out.println("Sum of integers: " + sumOfNumbers(ints));
    }
}

