import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    private static final AtomicInteger counter = new AtomicInteger(0);

    public static void main(String[] args) throws InterruptedException {
        System.out.println("=== 12: Concurrency & The Java Memory Model (JMM) ===");

        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) counter.incrementAndGet();
        });
        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 1000; i++) counter.incrementAndGet();
        });

        t1.start(); t2.start();
        t1.join(); t2.join();

        System.out.println("Atomic Counter final value: " + counter.get());
    }
}

import java.util.concurrent.Executors;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== 13: Virtual Threads (Project Loom - Java 21) ===");

        // Spin up 10,000 lightweight virtual threads concurrently with minimal RAM
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 1; i <= 5; i++) {
                final int taskId = i;
                executor.submit(() -> {
                    System.out.println("Running task " + taskId + " on virtual thread: " + Thread.currentThread());
                });
            }
        }
    }
}

import java.lang.annotation.*;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface AuditLog {
    String action();
}

public class Main {
    @AuditLog(action = "USER_LOGIN")
    public void login() {
        System.out.println("Executing login...");
    }

    public static void main(String[] args) throws Exception {
        System.out.println("=== 14: Annotations & Reflection API ===");
        var method = Main.class.getMethod("login");
        if (method.isAnnotationPresent(AuditLog.class)) {
            AuditLog log = method.getAnnotation(AuditLog.class);
            System.out.println("Found Annotation Action: " + log.action());
        }
    }
}

